import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
} from '@jinx-ui/react';

interface RegistrationFormProps {
  onSubmit: (data: {
    name: string;
    email: string;
    address: string;
    city: string;
  }) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');

  const nameError = step > 0 && name.trim().length === 0 ? 'Укажите имя' : undefined;
  const emailError = email.length > 0 && !email.includes('@') ? 'Укажите адрес с символом @' : undefined;
  const addressError = step > 1 && address.trim().length === 0 ? 'Укажите адрес' : undefined;
  const cityError = step > 1 && city.trim().length === 0 ? 'Укажите город' : undefined;

  const isStepValid = () => {
    if (step === 0) {
      return name.trim().length > 0 && email.trim().length > 0 && email.includes('@');
    }
    if (step === 1) {
      return address.trim().length > 0 && city.trim().length > 0;
    }
    return true;
  };

  const goNext = () => setStep((current) => Math.min(current + 1, steps.length - 1));
  const goBack = () => setStep((current) => Math.max(current - 1, 0));

  const handleSubmit = () => {
    onSubmit({ name, email, address, city });
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            value={name}
            onChange={(event) => setName(event.target.value)}
            errorText={nameError}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            errorText={emailError}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Город"
            required
            value={city}
            onChange={(event) => setCity(event.target.value)}
            errorText={cityError}
          />
          <JxTextareaField
            label="Адрес"
            required
            rows={3}
            value={address}
            onChange={(event) => setAddress(event.target.value)}
            errorText={addressError}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <p>
            <strong>Имя:</strong> {name || '—'}
          </p>
          <p>
            <strong>Почта:</strong> {email || '—'}
          </p>
          <p>
            <strong>Город:</strong> {city || '—'}
          </p>
          <p>
            <strong>Адрес:</strong> {address || '—'}
          </p>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '12px' }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" type="button" disabled={!isStepValid()} onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" type="button" onClick={handleSubmit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

